DAY = '2026-10-10'
SDK = pathlib.Path(os.environ.get('ANDROID_SDK_ROOT', os.environ.get('ANDROID_HOME', str(pathlib.Path.home() / 'Library/Android/sdk')))) / 'platforms/android-36/data/api-versions.xml'
