SOURCES = {}
def source(key, title, url, audit='official_reference', claim='Mechanism and interface reference, not evidence of project testing'):
    SOURCES[key] = {'title': title, 'url': url, 'accessedAt': DAY if audit=='web_content_reviewed' else None, 'registeredAt': DAY, 'audit': audit, 'claim': claim,
                    'publishedAt': None, 'publicationDateNote':'Living documentation has no single publication date; do not substitute the access date'}
