def api_source(symbol):
    key = symbol.replace('/','_')
    if key not in SOURCES:
        source(key, symbol.replace('/','.'), 'https://developer.android.com/reference/' + symbol)
    return key

CAP = []
def add(id,title,purpose,tier,symbol,permission,authorization,entry,code,expected,limits,
        status='research',evidence=(),sources=(),version='',kind='android_api_snippet',scope='',minimum=None):
    # API class appearance is explicitly separate from method/version policy constraints.
    c=api_classes.get(symbol); m=minimum if minimum is not None else (int(c.get('since','1')) if c is not None else 0)
    basis='First public SDK version of the interface class (not the minimum for every behavior described here)' if c is not None and minimum is None else ('Key method used by the example / project target version' if m else 'Non-public SDK, custom or device interface; no universal minimum API declaration')
    refs=list(sources)
    if c is not None: refs.insert(0,api_source(symbol))
    if not refs: refs=['perm']
    perms=[{'name':p.strip(),'authorization':authorization} for p in permission.split(';') if p.strip()] or [{'name':'No additional Manifest permission','authorization':authorization}]
    ev=[]
    for p in evidence:
        fresh='current-readonly' in p or 'apk-verification' in p or p=='evidence/sdk/sdk-device-report.json'
        ev.append({'path':p,'kind':'current_probe' if fresh else 'historical_artifact',
                   'verifiedAt':DAY,'executionDate':DAY if fresh else '2026-10-09 / 2026-10-10; see original records',
                   'scope':scope or 'Establishes only the specific behavior stated here; the GUI was not rerun in this review'})
    CAP.append({'id':id,'title':title,'purpose':purpose,'accessTier':tier,
      'androidSupport':{'apiMin':m or None,'minimumBasis':basis,'publicSdkClass':c is not None,'exampleApiMin':max(m,23) if kind=='android_api_snippet' and ('getSystemService(' in code or 'AudioRecord.Builder' in code) else (m or None), 'declaredVersionNotes':version or 'An API declaration is not a device guarantee; check targetSdk and the OEM branch.',
                        'devices':'Public APIs require corresponding hardware / OEM support; this inventory covers only AgentOS_ImageCheck ARM64, with no verified physical device',
                        'verified':['Android 16 / API 36 / ARM64 / AgentOS_ImageCheck / emulator-5582'] if status=='emulator_verified' else []},
      'permissions':perms,'entrypoints':[{'name':entry,'availability':'Existing experimental entry point' if status=='emulator_verified' else 'Upstream API / research implementation entry point; not an exposed Taku SDK method'}],
      'examples':[{'kind':kind,'environment':'Root shell on the phone' if kind=='device_shell' else ('Host terminal, explicitly targeting emulator-5582' if kind=='host_shell' else ('Kotlin method snippet in an ordinary Android project; complete Manifest, permissions and lifecycle as documented; not a directly executable CLI' if kind=='android_api_snippet' else 'Read-only source-location command in an AOSP checkout; not evidence of implemented functionality')),
                   'preconditions':authorization,'code':code,'expected':expected,'executedThisRun':False}],
      'limitations':limits,'status':status,'verificationScope':scope or ('Not tested; the example is a research entry point, not an installed Taku API' if status=='research' else 'See evidence and stated scope'),
      'evidence':ev,'sources':[SOURCES[k] for k in dict.fromkeys(refs)],
      'romRequirement':('The basic capability does not require flashing; the current experimental implementation may use higher privileges' if tier=='ordinary' else
                       'No custom ROM required; authorized ADB/shell access is needed; this project has not tested Shizuku integration' if tier=='adb_shizuku' else
                       'Requires appropriate root access or system signing/preinstallation; deployment on a rooted stock system may be possible, but this distribution path is unverified' if tier=='root_system' else
                       'The intended behavior requires Framework, system-policy or HAL integration; each device requires its own build and verification')})
