def build():
    for x in CAP:
        x['validation']={'research':{'status':'documented','scope':'Upstream mechanisms and research variants; see limitations for unfinished parts'},
                         'emulator':{'status':'passed_in_scope' if x['status']=='emulator_verified' else 'not_verified', 'target':'AgentOS_ImageCheck / API36 / ARM64','scope':x['verificationScope'],'date':DAY,'evidence':x['evidence']},
                         'physicalDevice':{'status':'not_verified','date':None,'devices':[],'evidence':[]}}
    counts=dict(collections.Counter(x['status'] for x in CAP)); counts.setdefault('device_verified',0)
    data={'schemaVersion':'0.1','updatedAt':DAY,'title':'Taku OS Android capability inventory',
      'verificationTarget':{'serial':'emulator-5582','avd':'AgentOS_ImageCheck','android':16,'api':36,'abi':'arm64-v8a','physicalDevicesVerified':0},
      'limitations':['The latest changes were installed only on a development emulator, not exported as a distributable ROM or verified on a physical phone.',
                     'Status applies to specific behavior; research extensions in the same entry do not pass merely because the basic probe passed.',
                     "The declared minimum public API version is not the project's supported version; physical devices, OEMs and permission policies require separate tests.",
                     'The capabilities inventory is a research/experimental catalog; SDK methods.list is the actual implemented-method list.'],
      'counts':counts,'capabilities':CAP}
    (ROOT/'spec/capabilities.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    (ROOT/'evidence/api-inventory/source-audit.json').write_text(json.dumps({'accessedAt':DAY,'sources':list(SOURCES.values()),
       'localApiVersionAuthority':{'origin':'Android SDK platforms/android-36/data/api-versions.xml','sha256':hashlib.sha256(SDK.read_bytes()).hexdigest(),'scope':'SDK36 class/method API since metadata, not runtime verification'},
       'notes':['web_content_reviewed means official pages/search results were actually read in that review; official_reference locates an interface without claiming full online review.','A citation supports the mechanism, not a claim that the product feature has been tested.']},ensure_ascii=False,indent=2)+'\n')
    guide=['# Taku OS Android permissions / API inventory','',f'Version 0.1 · {DAY} historical capability snapshot · for product evaluation and reproduction.','',
      f'This inventory contains {len(CAP)} entries: {counts.get("emulator_verified",0)} with specific emulator evidence, {counts.get("research",0)} research entry points, and 0 verified on a physical device. These counts are the **per-entry acceptance statistics for this inventory on {DAY}**, not the current project\'s total physical-device progress. Entries retain the status, versions and evidence scope recorded then.',
      "“Verified on an emulator” covers only the entry's verificationScope; it does not establish that related research variants, all apps or all versions passed.",'',
      '**Later progress (as of 2026-10-19):** A complete Pixel 9 development candidate was built on October 11. A package based on it was installed and booted on a physical phone on October 14. October 15 component acceptance covered real models, read-only Android tools and some recovery after cold boot; see [native client acceptance](native-codex-implementation-2026-10-15.md). That day also included [on-device native Java app generation, compilation, upgrades and business API acceptance](agent-system-app-acceptance-2026-10-15.md) on a dedicated emulator. This later evidence was not backfilled as per-item physical-device coverage for the 57 entries here and does not establish a successful build of the latest complete ROM. See [current progress](current-status.md) for consolidated status.','',
      '## How to use this inventory','',
      'Choose specific inputs and success criteria, then inspect the permission tier, entry point and limitations. Rerun verified entries against actual results using their examples. Research entries provide source locations and method-level snippets, not delivered general adapters. Kotlin snippets for ordinary APIs belong in a complete Android project with Manifest declarations, permission callbacks and lifecycle handling; they cannot be pasted into a phone shell. Source-location examples reproduce code locations, not feature calls.','',
      'Phone-shell examples run on authorized test devices; host examples must explicitly specify emulator-5582. An experimental entry point requiring root/system privileges does not become available to ordinary apps because it is wrapped in a CLI.','',
      'The SDK currently exposes a closed set of read-only system/display/task-state and discovery methods. Run `node sdk/cli/taku.mjs call methods.list` to inspect the actual set. Research capabilities in this inventory do not automatically become callable SDK methods. Phone-app business APIs are also distinct from low-level OS APIs.','',
      '## Flashing and permission tiers','',
      '|Tier|How to obtain it|Main boundaries|','|---|---|---|',
      '|Ordinary app|Runtime permissions, special access, default roles, URI grants|Camera, notifications and accessibility can work without flashing; there is no single grant for all permissions|',
      '|ADB / Shizuku|Developer debugging authorization; Shizuku shell service and app authorization|No custom ROM needed; shell is not root and OEMs may restrict it|',
      '|Root / system signing|Unlock/root or OEM platform signing and preinstallation; same-partition privapp allowlist|Does not necessarily require Framework changes and does not bypass SELinux/FBE/hardware trust boundaries|',
      '|ROM Framework / HAL|AOSP branch, device/vendor, service/policy/HAL integration|System lifecycle and global pipelines require builds and verification for each device/version|','',
      'The emulator used here has uid 0 and system test signing. System-signed apps and root services are distinct calling surfaces. Root deployment on stock systems, Shizuku integration and complete-image installation each require independent evidence; they cannot be inferred from these emulator records. The later Pixel 9 installation has separate [device evidence](../evidence/builds/2026-10-14-pixel9-install.json).','',
      '## Reproduction entry points','',
      'Environment verification without side effects: `python3 examples/capabilities/probe_readonly.py`. It has an AVD/serial allowlist and reads only versions, services, resources and explicitly named packages. It does not start/stop apps, retrieve account data or inject input.','',
      'Choose commands for emulator-verified capabilities from [examples/capabilities/README.md](../examples/capabilities/README.md). The probe does not automatically run examples that write, notify, launch or install. Serialize GUI tests that would contend with another worker for the main screen.','',
      'Standalone APK verification: `evidence/api-inventory/apk-verification.json` contains apksigner results, Manifests, SHA-256 and installed-file hashes for both packages. Matching results establish actual APKs rather than web previews.','',
      '## Failures and gaps at the time of this inventory','',
      '- WeChat 8.0.79: historical pre-login welcome/phone-number pages and targeted taps passed; no login, messaging, calls or payments were tested.',
      '- Xiaohongshu 9.49.1: guest image feed and Mirror scrolling/hide/resume passed historically; video, posting and accounts were untested.',
      '- Douyin 40.7.0: installation, native controls and switching worked; video showed green screens/colored artifacts, including some main-screen failures. Video compatibility did not pass. Standard HEVC raw decoding/Surface/GLES experiments passed, but the root cause remains unresolved.',
      '- Independent displays share user/data/audio resources; there is no guarantee of automatic pausing, takeover arbitration, multi-touch/keyboard forwarding or two instances of the same app.',
      '- This October 10 inventory did not accept a complete ROM or physical device. Later older-candidate builds, Pixel 9 installation and component acceptance are described above. A complete ROM corresponding to current source still needs building and acceptance; partial results cannot establish that the entire system is releasable.','',
      'This section preserves the compatibility scope at that time. Later individual features were verified separately, including [emulator background Unicode input](emulator-chinese-input-2026-10-14.md) and [child-process cleanup when the Agent stops](agent-cancellation-2026-10-15.md). They do not establish generic takeover arbitration, two instances of one app or complete app compatibility.','',
      '## All capabilities','']
    for x in CAP:
        guide += [f'### {x["title"]} · `{x["id"]}`','',f'**Purpose:** {x["purpose"]}',f'**Tier:** {TIER[x["accessTier"]]}. {x["romRequirement"]}',
          f'**Status:** {STATE[x["status"]]}. {x["verificationScope"]}',f'**Version/device:** Minimum declared API {x["androidSupport"]["apiMin"] or 'No universal declaration'}; {x["androidSupport"]["minimumBasis"]}. This example starts at API {x["androidSupport"]["exampleApiMin"] or 'No universal declaration'}. {x["androidSupport"]["declaredVersionNotes"]}; {x["androidSupport"]["devices"]}',
          '**Entry point:** '+x['entrypoints'][0]['name'], '**Permissions/authorization:** '+ '; '.join(p['name']+': '+p['authorization'] for p in x['permissions']), '']
        e=x['examples'][0];guide += [f'**Example ({e["environment"]}): **','', '```'+('kotlin' if e['kind']=='android_api_snippet' else 'sh'),e['code'],'```','', '**Expected result / success criteria:** '+e['expected'],'', '**Limitations:**',''] + ['- '+s for s in x['limitations']]
        guide += ['','**Evidence:** '+('; '.join(f'[{pathlib.Path(e["path"]).name}](../{e["path"]})' for e in x['evidence']) or 'No execution evidence yet.'),
                  '**Primary sources:** '+'; '.join(f'[{s["title"]}]({s["url"]})' for s in x['sources'])+'. Access/registration date '+DAY+'.','']
    (ROOT/'docs/android-api-guide.md').write_text('\n'.join(guide))
    example=['# Capability call examples','', 'Run from the repository root. This directory supplies reproduction entry points, not a second OS protocol or task queue.','',
      'Probe without side effects: `python3 examples/capabilities/probe_readonly.py`. A person/Agent selects scenarios for other examples; avoid indiscriminate batches of taps, notifications or installs.','',
      '|Capability|Execution environment|Example type|','|---|---|---|']
    for x in CAP:
        e=x['examples'][0]; ext='kt' if e['kind']=='android_api_snippet' else 'sh'
        p=ROOT/'examples/capabilities'/f'{x["id"]}.{ext}'
        prefix='// ' if ext=='kt' else '# '
        p.write_text(prefix+x['title']+' · '+STATE[x['status']]+'\n'+prefix+'Environment: '+e['environment']+'\n'+prefix+'Prerequisites: '+e['preconditions']+'\n'+prefix+'Expected result: '+e['expected']+'\n'+prefix+'This review did not automatically execute this example; define scenario-specific success criteria first.\n'+e['code']+'\n')
        example.append(f'|[{x["title"]}]({p.name})|{e["environment"]}|{e["kind"]}|')
    example += ['', 'Kotlin examples are method-level development snippets, not complete runnable APKs. Source-location commands are read-only research. See android-api-guide for authorization, limitations and verification scope; do not relabel research examples as tested.',
                '', 'Phone-app business API source is in tooling/app-kit, and its device runtime must be deployed separately. A clean source checkout does not install that runtime automatically. Examples labeled as existing experimental entry points require an explicit development-device deployment prerequisite; a script directory name is not evidence of installation.']
    (ROOT/'examples/capabilities/README.md').write_text('\n'.join(example)+'\n')
    render_site(data)
    print(json.dumps({'capabilities':len(CAP),'counts':counts,'sources':len(SOURCES)},ensure_ascii=False))

def render_site(data):
    payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Taku OS · Capability catalog</title>
<style>:root{--ink:#263628;--bg:#f4f4ee;--line:#d1d8c8;--moss:#506b48}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:15px/1.65 system-ui,-apple-system,sans-serif}a{color:#345e44}header{padding:44px 5vw 28px;border-bottom:1px solid var(--line);background:#e8edde}header small{letter-spacing:.18em}h1{font-size:42px;line-height:1.15;margin:14px 0}p{max-width:850px}.stats{display:flex;gap:30px;flex-wrap:wrap}.stats b{font-size:28px;margin-right:5px}.filters{padding:18px 5vw;position:sticky;top:0;z-index:1;background:#f4f4eef2;backdrop-filter:blur(8px);border-bottom:1px solid var(--line);display:flex;gap:10px;flex-wrap:wrap}input,select{font:inherit;background:white;border:1px solid #b8c4ac;border-radius:8px;padding:9px 12px}input{min-width:230px;flex:1}main{padding:24px 5vw 60px}.note{border-left:3px solid #a76e40;padding:10px 18px;background:#fbf0e4;margin-bottom:22px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}article{border:1px solid var(--line);background:#fffef9;border-radius:14px;padding:22px;min-width:0}article h2{margin:8px 0;font-size:21px}article p{margin:8px 0}.badge{font-size:12px;padding:3px 7px;border-radius:4px;background:#eeeee8}.tested{background:#dfecd7;color:#355230}.research{background:#f0e4d4;color:#875324}.meta{color:#667160;font-size:13px}summary{cursor:pointer;color:#345e44;font-weight:600;padding:10px 0}dl{margin:8px 0}dt{font-weight:650;margin-top:12px}dd{margin:4px 0}pre{background:#243023;color:#edf5e7;padding:14px;border-radius:8px;white-space:pre-wrap;word-break:break-word;font-size:12px;line-height:1.7}ul{padding-left:20px}.empty{padding:50px;text-align:center}footer{font-size:12px;color:#697460;padding:20px 5vw;border-top:1px solid var(--line)}@media(max-width:550px){h1{font-size:32px}.cards{grid-template-columns:1fr}header{padding-top:30px}.filters{position:relative}.stats{gap:16px}article{padding:18px}}</style>
<header><small>TAKU OS / DEVELOPER CAPABILITIES / 0.1</small><h1>Explore available capabilities<br>Then choose a use case</h1><p>Flashing enables system integration and lifecycle control, but many capabilities already exist in ordinary apps or authorized ADB. Each card records permissions, actual entry points, versions and evidence separately. Research entries do not automatically become exposed SDK methods.</p><div class="stats" id="stats"></div></header>
<div class="filters"><input id="q" aria-label="Search capabilities" placeholder="Search notifications, background displays, camera, root, APIs…"><select id="tier" aria-label="Permission tier"><option value="">All permission paths</option><option value="ordinary">Ordinary app · No flashing</option><option value="adb_shizuku">ADB / Shizuku · No custom ROM</option><option value="root_system">Root / system signing</option><option value="rom_framework">ROM Framework / HAL changes</option></select><select id="status" aria-label="Verification status"><option value="">All statuses</option><option value="research">Research proposal</option><option value="emulator_verified">Emulator verified</option><option value="device_verified">Physical device verified</option></select><select id="version" aria-label="Verified version"><option value="">All version scopes</option><option value="verified36">API 36 with evidence</option><option value="public">Public API declaration (not a test)</option><option value="internal">Custom/system interfaces</option></select></div>
<main><div class="note"><b>Historical capability snapshot · 2026-10-10:</b>Of the 57 entries here, 20 have emulator evidence, 37 are research entry points and 0 have physical-device acceptance. These counts cover this registration batch only, not all project acceptance. Cards preserve the devices, versions, failures and gaps recorded then, and label each example type.<br><b>Later progress · As of 2026-10-19:</b>An older candidate completed a full build on October 11, Pixel 9 installation on October 14, and partial physical-device component/cold-boot recovery acceptance on October 15. The latest complete-ROM build corresponding to the then-current source still had a failure record.<br><a href="../docs/current-status.md">Current project status</a> · <a href="../docs/android-api-guide.md">Engineering guide</a> · <a href="../spec/capabilities.json">Structured inventory</a> · <a href="../evidence/api-inventory/current-readonly.json">Read-only probe from this review</a> · <a href="../evidence/api-inventory/apk-verification.json">Standalone APK verification</a></div><p class="meta" id="count" aria-live="polite"></p><div class="cards" id="cards"></div></main><footer>This registration batch covers only AgentOS_ImageCheck / emulator-5582 / Android 16 API 36 / ARM64. See current status for later acceptance. Sources: public Android mechanisms, pinned SDK36 declarations, historical native evidence and the scoped read-only probe. Access/registration date: 2026-10-10; a living document's access date is not its publication date.</footer>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent), E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tiers={ordinary:'Ordinary app · No flashing',adb_shizuku:'ADB / Shizuku · No custom ROM',root_system:'Root / system signing',rom_framework:'ROM / Framework / HAL'};
const states={research:'Research proposal',emulator_verified:'Emulator verified · Within evidence scope',device_verified:'Physical device verified'};
document.querySelector('#stats').innerHTML=`<span><b>${D.capabilities.length}</b>capability entries</span><span><b>${D.counts.emulator_verified||0}</b>with emulator evidence</span><span><b>${D.counts.research||0}</b>research entries</span><span><b>0</b>physical-device passes in this batch</span>`;
function render(){let q=document.querySelector('#q').value.trim().toLowerCase(),tier=document.querySelector('#tier').value,status=document.querySelector('#status').value,v=document.querySelector('#version').value;
let list=D.capabilities.filter(c=>(!q||JSON.stringify(c).toLowerCase().includes(q))&&(!tier||c.accessTier===tier)&&(!status||c.status===status)&&(!v||(v==='verified36'?c.androidSupport.verified.length>0:v==='public'?c.androidSupport.publicSdkClass:!c.androidSupport.publicSdkClass)));
document.querySelector('#count').textContent=`Showing ${list.length} / ${D.capabilities.length} entries`;
document.querySelector('#cards').innerHTML=list.length?list.map(c=>{let e=c.examples[0];return `<article><span class="badge ${c.status==='research'?'research':'tested'}">${E(states[c.status])}</span><h2>${E(c.title)}</h2><div class="meta">${E(c.id)} · ${E(tiers[c.accessTier])}</div><p>${E(c.purpose)}</p><p class="meta">${E(c.verificationScope)}</p><details><summary>Permissions, versions and reproducible examples</summary><dl><dt>Entry point</dt><dd>${E(c.entrypoints[0].name)}</dd><dt>Permissions and authorization</dt><dd>${c.permissions.map(p=>`${E(p.name)}: ${E(p.authorization)}`).join('<br>')}</dd><dt>Android and device</dt><dd>Minimum declared API ${c.androidSupport.apiMin||'No universal declaration'}; ${E(c.androidSupport.minimumBasis)}. ${E(c.androidSupport.declaredVersionNotes)}<br>${E(c.androidSupport.devices)}<br>Verified: ${E(c.androidSupport.verified.join('; ')||'None')}</dd><dt>Example type / environment</dt><dd>${E(e.kind)} · ${E(e.environment)}</dd><dt>Call example</dt><dd><pre>${E(e.code)}</pre></dd><dt>Success criteria</dt><dd>${E(e.expected)}</dd><dt>Limitations</dt><dd><ul>${c.limitations.map(s=>`<li>${E(s)}</li>`).join('')}</ul></dd><dt>Evidence</dt><dd>${c.evidence.map(p=>`<a href="../${E(p.path)}">${E(p.path.split('/').pop())}</a> · ${E(p.kind)}<br>`).join('')||'No execution evidence yet'}</dd><dt>Primary sources</dt><dd>${c.sources.map(s=>`<a href="${E(s.url)}" target="_blank" rel="noopener">${E(s.title)}</a> · ${E(s.audit)}<br>`).join('')}</dd></dl></details></article>`}).join(''):'<div class="empty">No entries in this historical batch match these filters. See current status for later project acceptance.</div>';}
['q','tier','status','version'].forEach(id=>document.querySelector('#'+id).addEventListener('input',render));render();
</script></html>'''
    (ROOT/'site/capabilities.html').write_text(template.replace('__DATA__',payload))

if __name__=='__main__': build()
